// Helper functions
export function getHomeByUrl(url: string): PageData | undefined {
  const cleanUrl = url.replace(/^\/+|\/+$/g, "");
  return homeData.pages.find(
    (page) =>
      page.url === url ||
      page.url === `/${url}` ||
      page.url.replace(/^\/+|\/+$/g, "") === cleanUrl,
  );
}

export function getHomeByKeyword(keyword: string): PageData[] {
  return homeData.pages.filter(
    (page) =>
      page.metadata.primaryKeyword === keyword ||
      page.metadata.secondaryKeywords.includes(keyword),
  );
}

